#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/sensor.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/sensor/adltc2990.h>
#include <zephyr/drivers/sensor/adltc2990/emul/adltc2990_emul.h>
#include <zephyr/ztest.h>
#include <zephyr/ztest_assert.h>

#define ADLTC2990_DEV_LABEL DT_LABEL(DT_INST(0, adi_adltc2990))

static const struct device *adltc2990_dev = DEVICE_DT_GET(DT_INST(0, adi_adltc2990));

static void test_adltc2990_init(void)
{
    zassert_true(device_is_ready(adltc2990_dev), "ADLTC2990 device is not ready");
}

static void test_adltc2990_read_voltage(void)
{
    struct sensor_value val;
    int rc;

    /* In a real test, emulator functions would be used here to set expected values */
    /* For example: adltc2990_emul_set_voltage(adltc2990_dev, 1.234); */

    rc = sensor_sample_fetch(adltc2990_dev);
    zassert_equal(rc, 0, "Failed to fetch sample");

    /* Assuming SENSOR_CHAN_VOLTAGE is a valid channel for ADLTC2990 */
    rc = sensor_channel_get(adltc2990_dev, SENSOR_CHAN_VOLTAGE, &val);
    zassert_equal(rc, 0, "Failed to get voltage channel");

    /* Placeholder for actual value assertion based on emulator setup */
    /* zassert_equal(val.val1, 1, "Voltage integer part incorrect"); */
    /* zassert_equal(val.val2, 234000, "Voltage fractional part incorrect"); */
}

ZTEST_SUITE(adltc2990_driver_tests, NULL, NULL, NULL, NULL, NULL);

ZTEST(adltc2990_driver_tests, test_init)
{
    test_adltc2990_init();
}

ZTEST(adltc2990_driver_tests, test_read_voltage)
{
    test_adltc2990_read_voltage();
}
